/**
 * Render a neon sign SVG by index.
 * The SVGs carry their own colors — no external color param needed.
 */
export function NeonSignSVG({ index, size }: { index: number; size: number }): React.ReactElement {
  const i = ((index % NEON_SIGN_COUNT) + NEON_SIGN_COUNT) % NEON_SIGN_COUNT;
  return (
    <svg
      viewBox={VIEW_BOXES[i]}
      width={size}
      height={size}
      xmlns="http://www.w3.org/2000/svg"
      style={{ overflow: "visible" }}
      dangerouslySetInnerHTML={{ __html: NEON_INNER[i] }}
    />
  );
}
